1	package nexusbench
2	
3	import (
4		"errors"
5		"fmt"
6		"math/big"
7		"net"
8		"net/url"
9		"regexp"
10		"strconv"
11		"strings"
12		"time"
13	)
14	
15	// Environment variables read by FromEnv. An empty value counts as unset.
16	const (
17		envContext        = "NEXUS_BENCH_CONTEXT"
18		envNamespace      = "NEXUS_BENCH_NAMESPACE"
19		envHTTPNodePort   = "NEXUS_BENCH_HTTP_NODEPORT"
20		envDockerNodePort = "NEXUS_BENCH_DOCKER_NODEPORT"
21		envCPURequest     = "NEXUS_BENCH_CPU_REQUEST"
22		envCPULimit       = "NEXUS_BENCH_CPU_LIMIT"
23		envMemoryRequest  = "NEXUS_BENCH_MEMORY_REQUEST"
24		envMemoryLimit    = "NEXUS_BENCH_MEMORY_LIMIT"
25		envStorageSize    = "NEXUS_BENCH_STORAGE_SIZE"
26		envJVMOpts        = "NEXUS_BENCH_JVM_OPTS"
27		envImage          = "NEXUS_BENCH_IMAGE"
28		envImageTag       = "NEXUS_BENCH_IMAGE_TAG"
29		envUpstreamURL    = "NEXUS_BENCH_UPSTREAM_URL"
30		envAnonymous      = "NEXUS_BENCH_ANONYMOUS"
31		envAcceptEULA     = "NEXUS_BENCH_ACCEPT_EULA"
32		envHosts          = "NEXUS_BENCH_HOSTS"
33		envTimeout        = "NEXUS_BENCH_TIMEOUT"
34		envDeleteTimeout  = "NEXUS_BENCH_DELETE_TIMEOUT"
35		envSecrets        = "NEXUS_BENCH_SECRETS"
36		envDescriptor     = "NEXUS_BENCH_DESCRIPTOR"
37	)
38	
39	const (
40		// Defaults of D-B and D-C. The NodePorts were free on 2026-11-16; the block
41		// 30483-30489 stays reserved for the next NX stories.
42		defaultContext        = "datomir"
43		defaultNamespace      = "nexus-bench"
44		defaultHTTPNodePort   = 30481
45		defaultDockerNodePort = 30482
46		defaultImage          = "docker.io/sonatype/nexus3"
47		defaultImageTag       = "3.98.1"
48		defaultJVMOpts        = "-Xms1g -Xmx1g -XX:MaxDirectMemorySize=1g -Djava.util.prefs.userRoot=/nexus-data/javaprefs"
49	
50		nodePortMin = 30000
51		nodePortMax = 32767
52	
53		// zotRegistry is the registry the Kyverno policy verify-tvp-images guards:
54		// an image from it must be signed, and the bench image is not.
55		zotRegistry = "tvp-zot.incus:5000"
56	
57		maxJVMOptsLen   = 512
58		maxImageLen     = 255
59		maxHostLen      = 253
60		maxPathLen      = 4096
61		maxContextLen   = 253 // a kubeconfig context name is bounded like a DNS name
62		maxNamespaceLen = 63  // a DNS-1123 label
63		maxTCPPort      = 65535
64	)
65	
66	var (
67		// dns1123Label is a Kubernetes namespace name; the length is checked apart.
68		dns1123Label = regexp.MustCompile(`^[a-z0-9]([-a-z0-9]*[a-z0-9])?$`)
69		// contextName is kept to characters that are safe in a file name and in a
70		// kubectl argument: the context names a directory of the secrets path.
71		contextName = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._@-]*$`)
72		// cpuQuantity is a Kubernetes CPU quantity: whole or decimal cores, or milli-cores.
73		cpuQuantity = regexp.MustCompile(`^([0-9]+(\.[0-9]+)?|[0-9]+m)$`)
74		// byteQuantity is a Kubernetes quantity of bytes: a number and an optional
75		// binary (Ki..Ei) or decimal (k, M, G, T, P, E) suffix. Exponent forms are not accepted.
76		byteQuantity = regexp.MustCompile(`^([0-9]+(?:\.[0-9]+)?)(Ki|Mi|Gi|Ti|Pi|Ei|k|M|G|T|P|E)?$`)
77		// jvmOptsChars rules out quotes, backslashes, braces, '#', '&', '*', '!',
78		// '|', '>' and every control character (newlines included), so a value
79		// cannot end a YAML scalar or start another node.
80		jvmOptsChars = regexp.MustCompile(`^[A-Za-z0-9 _.,:=/+@%-]+$`)
81		// jvmOptsStart keeps the first character from being a YAML indicator: a
82		// letter, a digit, or '-' followed by a non-space (so not "- x", a sequence entry).
83		jvmOptsStart = regexp.MustCompile(`^([A-Za-z0-9]|-[^ ])`)
84		imageChars   = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._/:-]*$`)
85		imageTag     = regexp.MustCompile(`^[A-Za-z0-9_][A-Za-z0-9_.-]{0,127}$`)
86		hostName     = regexp.MustCompile(`^[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?$`)
87		urlChars     = regexp.MustCompile(`^[A-Za-z0-9._~:/%-]+$`)
88	)
89	
90	// reservedNamespaces are namespaces the bench must never create, adopt or
91	// delete, whatever their label says. Matching is on the lower-cased name.
92	var reservedNamespaces = map[string]bool{
93		"default":            true,
94		"flux-system":        true,
95		"local-path-storage": true,
96		"traefik":            true,
97		"kyverno":            true,
98		"observability":      true,
99		"plane":              true,
100	}
101	
102	// reservedNamespacePrefixes are the families of namespaces owned by someone else.
103	var reservedNamespacePrefixes = []string{"kube-", "app-"}
104	
105	// Params is everything that varies between two runs of the bench. Resolve it
106	// with Defaults, then FromEnv, then the command flags, then Validate before any
107	// call to the cluster: the manifests are rendered from validated values only.
108	type Params struct {
109		Context, Namespace, Image, ImageTag string
110		HTTPNodePort, DockerNodePort        int
111		CPURequest, CPULimit                string
112		MemoryRequest, MemoryLimit          string
113		StorageSize, JVMOpts                string
114		UpstreamURL                         string
115		Anonymous, AcceptEULA               bool
116		// Hosts are the addresses the NodePorts are tried on; nil means the tool
117		// works them out (127.0.0.1 and the node's InternalIP).
118		Hosts                       []string
119		Timeout, DeleteTimeout      time.Duration
120		SecretsPath, DescriptorPath string
121	}
122	
123	// Defaults returns the parameters of the bench as D-B and D-C define them.
124	// Hosts, SecretsPath and DescriptorPath stay empty: the tool derives them.
125	func Defaults() Params {
126		return Params{
127			Context:        defaultContext,
128			Namespace:      defaultNamespace,
129			Image:          defaultImage,
130			ImageTag:       defaultImageTag,
131			HTTPNodePort:   defaultHTTPNodePort,
132			DockerNodePort: defaultDockerNodePort,
133			CPURequest:     "500m",
134			CPULimit:       "2",
135			MemoryRequest:  "3Gi",
136			MemoryLimit:    "4Gi",
137			StorageSize:    "5Gi",
138			JVMOpts:        defaultJVMOpts,
139			UpstreamURL:    upstreamFor(defaultNamespace),
140			Anonymous:      true,
141			Timeout:        10 * time.Minute,
142			DeleteTimeout:  3 * time.Minute,
143		}
144	}
145	
146	// upstreamFor is the in-cluster URL of the upstream registry NX-02 creates in a namespace.
147	func upstreamFor(namespace string) string {
148		return "http://bench-upstream." + namespace + ".svc.cluster.local:5000"
149	}
150	
151	// ImageRef returns the image reference of the Nexus container, "image:tag".
152	func (p Params) ImageRef() string {
153		return p.Image + ":" + p.ImageTag
154	}
155	
156	// envSetter applies the value of one non-empty variable to p.
157	type envSetter struct {
158		name  string
159		apply func(p *Params, value string) error
160	}
161	
162	func stringSetter(name string, field func(p *Params) *string) envSetter {
163		return envSetter{name, func(p *Params, v string) error {
164			*field(p) = v
165			return nil
166		}}
167	}
168	
169	func portSetter(name string, field func(p *Params) *int) envSetter {
170		return envSetter{name, func(p *Params, v string) error {
171			n, err := strconv.Atoi(v)
172			if err != nil {
173				return fmt.Errorf("%s: %q is not a whole number", name, v)
174			}
175			*field(p) = n
176			return nil
177		}}
178	}
179	
180	func durationSetter(name string, field func(p *Params) *time.Duration) envSetter {
181		return envSetter{name, func(p *Params, v string) error {
182			d, err := time.ParseDuration(v)
183			if err != nil {
184				return fmt.Errorf("%s: %q is not a duration such as 90s or 10m", name, v)
185			}
186			*field(p) = d
187			return nil
188		}}
189	}
190	
191	func boolSetter(name string, field func(p *Params) *bool) envSetter {
192		return envSetter{name, func(p *Params, v string) error {
193			b, err := strconv.ParseBool(v)
194			if err != nil {
195				return fmt.Errorf("%s: %q is not true or false", name, v)
196			}
197			*field(p) = b
198			return nil
199		}}
200	}
201	
202	// envSetters lists every variable but the namespace, which FromEnv handles
203	// itself because it also moves the upstream URL.
204	var envSetters = []envSetter{
205		stringSetter(envContext, func(p *Params) *string { return &p.Context }),
206		portSetter(envHTTPNodePort, func(p *Params) *int { return &p.HTTPNodePort }),
207		portSetter(envDockerNodePort, func(p *Params) *int { return &p.DockerNodePort }),
208		stringSetter(envCPURequest, func(p *Params) *string { return &p.CPURequest }),
209		stringSetter(envCPULimit, func(p *Params) *string { return &p.CPULimit }),
210		stringSetter(envMemoryRequest, func(p *Params) *string { return &p.MemoryRequest }),
211		stringSetter(envMemoryLimit, func(p *Params) *string { return &p.MemoryLimit }),
212		stringSetter(envStorageSize, func(p *Params) *string { return &p.StorageSize }),
213		stringSetter(envJVMOpts, func(p *Params) *string { return &p.JVMOpts }),
214		stringSetter(envImage, func(p *Params) *string { return &p.Image }),
215		stringSetter(envImageTag, func(p *Params) *string { return &p.ImageTag }),
216		stringSetter(envUpstreamURL, func(p *Params) *string { return &p.UpstreamURL }),
217		boolSetter(envAnonymous, func(p *Params) *bool { return &p.Anonymous }),
218		// Accepting a license is the user's decision: only the exact word "yes" counts.
219		{envAcceptEULA, func(p *Params, v string) error {
220			p.AcceptEULA = v == "yes"
221			return nil
222		}},
223		{envHosts, func(p *Params, v string) error {
224			p.Hosts = splitList(v)
225			return nil
226		}},
227		durationSetter(envTimeout, func(p *Params) *time.Duration { return &p.Timeout }),
228		durationSetter(envDeleteTimeout, func(p *Params) *time.Duration { return &p.DeleteTimeout }),
229		stringSetter(envSecrets, func(p *Params) *string { return &p.SecretsPath }),
230		stringSetter(envDescriptor, func(p *Params) *string { return &p.DescriptorPath }),
231	}
232	
233	// FromEnv returns base with every non-empty NEXUS_BENCH_* variable applied; base
234	// itself is left untouched. A value that cannot be parsed is an error that names
235	// its variable. Setting only NEXUS_BENCH_NAMESPACE moves the upstream URL to the
236	// new namespace, unless base already carries a custom one or
237	// NEXUS_BENCH_UPSTREAM_URL is set. FromEnv checks the shape of numbers,
238	// durations and booleans only; Validate checks the values.
239	func FromEnv(base Params, getenv func(string) string) (Params, error) {
240		p := base
241		if base.Hosts != nil {
242			p.Hosts = append([]string(nil), base.Hosts...)
243		}
244	
245		followsNamespace := base.UpstreamURL == upstreamFor(base.Namespace)
246		if v := getenv(envNamespace); v != "" {
247			p.Namespace = v
248		}
249		for _, s := range envSetters {
250			v := getenv(s.name)
251			if v == "" {
252				continue
253			}
254			if err := s.apply(&p, v); err != nil {
255				return base, err
256			}
257		}
258		if followsNamespace && getenv(envUpstreamURL) == "" {
259			p.UpstreamURL = upstreamFor(p.Namespace)
260		}
261		return p, nil
262	}
263	
264	// splitList splits a comma-separated list, trimming blanks and dropping empty items.
265	func splitList(v string) []string {
266		var out []string
267		for _, item := range strings.Split(v, ",") {
268			if item = strings.TrimSpace(item); item != "" {
269				out = append(out, item)
270			}
271		}
272		return out
273	}
274	
275	// Validate refuses any value the bench must not act on or render into a
276	// manifest. It reports every problem at once, each naming its variable, and
277	// never contacts the cluster.
278	func (p Params) Validate() error {
279		var errs []error
280		add := func(err error) {
281			if err != nil {
282				errs = append(errs, err)
283			}
284		}
285	
286		add(validateContext(p.Context))
287		add(validateNamespace(p.Namespace))
288		add(validateNodePort(envHTTPNodePort, p.HTTPNodePort))
289		add(validateNodePort(envDockerNodePort, p.DockerNodePort))
290		if p.HTTPNodePort == p.DockerNodePort {
291			add(fmt.Errorf("%s and %s are both %d: the two NodePorts must differ", envHTTPNodePort, envDockerNodePort, p.HTTPNodePort))
292		}
293		add(validateQuantity(envCPURequest, p.CPURequest, parseCPU, "cores such as 2 or 500m"))
294		add(validateQuantity(envCPULimit, p.CPULimit, parseCPU, "cores such as 2 or 500m"))
295		add(validateQuantity(envMemoryRequest, p.MemoryRequest, parseBytes, "bytes such as 3Gi"))
296		add(validateQuantity(envMemoryLimit, p.MemoryLimit, parseBytes, "bytes such as 4Gi"))
297		add(validateQuantity(envStorageSize, p.StorageSize, parseBytes, "bytes such as 5Gi"))
298		add(validateRequestLimit(envCPURequest, p.CPURequest, envCPULimit, p.CPULimit, parseCPU))
299		add(validateRequestLimit(envMemoryRequest, p.MemoryRequest, envMemoryLimit, p.MemoryLimit, parseBytes))
300		add(validateJVMOpts(p.JVMOpts))
301		add(validateImage(p.Image, p.ImageTag))
302		add(validateUpstreamURL(p.UpstreamURL))
303		add(validateHosts(p.Hosts))
304		add(validateTimeout(envTimeout, p.Timeout))
305		add(validateTimeout(envDeleteTimeout, p.DeleteTimeout))
306		add(validatePath(envSecrets, p.SecretsPath))
307		add(validatePath(envDescriptor, p.DescriptorPath))
308		return errors.Join(errs...)
309	}
310	
311	func validateContext(v string) error {
312		if len(v) > maxContextLen || !contextName.MatchString(v) {
313			return fmt.Errorf("%s: %q is not a usable context name (letters, digits, '.', '_', '@' and '-', starting with a letter or digit)", envContext, v)
314		}
315		return nil
316	}
317	
318	func validateNamespace(v string) error {
319		lower := strings.ToLower(v)
320		reserved := reservedNamespaces[lower]
321		for _, prefix := range reservedNamespacePrefixes {
322			reserved = reserved || strings.HasPrefix(lower, prefix)
323		}
324		if reserved {
325			return fmt.Errorf("%s: namespace %q belongs to the cluster or to another project and is never used by the bench (refused: default, kube-*, app-*, flux-system, local-path-storage, traefik, kyverno, observability, plane)", envNamespace, v)
326		}
327		if len(v) > maxNamespaceLen || !dns1123Label.MatchString(v) {
328			return fmt.Errorf("%s: %q is not a Kubernetes namespace name (lower-case letters, digits and '-', %d characters at most, starting and ending with a letter or digit)", envNamespace, v, maxNamespaceLen)
329		}
330		return nil
331	}
332	
333	func validateNodePort(name string, port int) error {
334		if port < nodePortMin || port > nodePortMax {
335			return fmt.Errorf("%s: %d is outside the NodePort range %d-%d", name, port, nodePortMin, nodePortMax)
336		}
337		return nil
338	}
339	
340	// quantityParser turns a Kubernetes quantity into a comparable amount (milli-cores
341	// or bytes); ok is false when the text is not a quantity of that kind.
342	type quantityParser func(v string) (amount *big.Rat, ok bool)
343	
344	// parseCPU returns a CPU quantity in milli-cores. big.Rat keeps "0.0005" and
345	// huge values exact, which an int64 would not.
346	func parseCPU(v string) (*big.Rat, bool) {
347		if !cpuQuantity.MatchString(v) {
348			return nil, false
349		}
350		number, milli := strings.CutSuffix(v, "m")
351		r, ok := new(big.Rat).SetString(number)
352		if !ok {
353			return nil, false
354		}
355		if !milli {
356			r.Mul(r, big.NewRat(1000, 1))
357		}
358		return r, true
359	}
360	
361	// byteMultipliers maps the suffixes byteQuantity accepts to their value in bytes.
362	var byteMultipliers = map[string]*big.Int{
363		"":   big.NewInt(1),
364		"Ki": new(big.Int).Lsh(big.NewInt(1), 10),
365		"Mi": new(big.Int).Lsh(big.NewInt(1), 20),
366		"Gi": new(big.Int).Lsh(big.NewInt(1), 30),
367		"Ti": new(big.Int).Lsh(big.NewInt(1), 40),
368		"Pi": new(big.Int).Lsh(big.NewInt(1), 50),
369		"Ei": new(big.Int).Lsh(big.NewInt(1), 60),
370		"k":  big.NewInt(1e3),
371		"M":  big.NewInt(1e6),
372		"G":  big.NewInt(1e9),
373		"T":  big.NewInt(1e12),
374		"P":  big.NewInt(1e15),
375		"E":  big.NewInt(1e18),
376	}
377	
378	// parseBytes returns a quantity of bytes.
379	func parseBytes(v string) (*big.Rat, bool) {
380		m := byteQuantity.FindStringSubmatch(v)
381		if m == nil {
382			return nil, false
383		}
384		r, ok := new(big.Rat).SetString(m[1])
385		if !ok {
386			return nil, false
387		}
388		return r.Mul(r, new(big.Rat).SetInt(byteMultipliers[m[2]])), true
389	}
390	
391	func validateQuantity(name, v string, parse quantityParser, hint string) error {
392		amount, ok := parse(v)
393		if !ok {
394			return fmt.Errorf("%s: %q is not a Kubernetes quantity of %s", name, v, hint)
395		}
396		if amount.Sign() == 0 {
397			return fmt.Errorf("%s: %q is zero; the quantity must be greater than zero", name, v)
398		}
399		return nil
400	}
401	
402	// validateRequestLimit refuses a request above its limit, which Kubernetes
403	// rejects at admission. A value that is not a quantity is reported by
404	// validateQuantity, not here.
405	func validateRequestLimit(requestName, request, limitName, limit string, parse quantityParser) error {
406		req, okReq := parse(request)
407		lim, okLim := parse(limit)
408		if okReq && okLim && req.Cmp(lim) > 0 {
409			return fmt.Errorf("%s and %s: the request %q is above the limit %q; the request must not exceed the limit", requestName, limitName, request, limit)
410		}
411		return nil
412	}
413	
414	func validateJVMOpts(v string) error {
415		if v == "" || len(v) > maxJVMOptsLen || !jvmOptsChars.MatchString(v) {
416			return fmt.Errorf("%s: %q must be 1-%d characters among letters, digits, space and _ . , : = / + @ %% -", envJVMOpts, v, maxJVMOptsLen)
417		}
418		// A leading indicator ("- ", "@", "%", ",", ":", a space) would stop the value
419		// from being a plain YAML scalar when it is written unquoted.
420		if !jvmOptsStart.MatchString(v) {
421			return fmt.Errorf("%s: %q must start with a letter, a digit, or '-' followed by a non-space character", envJVMOpts, v)
422		}
423		// ": " and a trailing ":" would turn a plain YAML scalar into a mapping key.
424		if strings.Contains(v, ": ") || strings.HasSuffix(v, ":") {
425			return fmt.Errorf("%s: %q must not hold \": \" or end with a colon", envJVMOpts, v)
426		}
427		return nil
428	}
429	
430	func validateImage(image, tag string) error {
431		if strings.HasPrefix(strings.ToLower(image), zotRegistry) {
432			return fmt.Errorf("%s: %q is in %s, where the Kyverno policy verify-tvp-images only admits signed images and the bench image is not signed; use an image from another registry", envImage, image, zotRegistry)
433		}
434		if len(image) > maxImageLen || !imageChars.MatchString(image) {
435			return fmt.Errorf("%s: %q is not an image name without tag or digest", envImage, image)
436		}
437		if !imageTag.MatchString(tag) {
438			return fmt.Errorf("%s: %q is not an image tag", envImageTag, tag)
439		}
440		return nil
441	}
442	
443	func validateUpstreamURL(v string) error {
444		u, err := url.Parse(v)
445		if err != nil || !urlChars.MatchString(v) {
446			return fmt.Errorf("%s: %q is not a plain http or https URL", envUpstreamURL, v)
447		}
448		if (u.Scheme != "http" && u.Scheme != "https") || u.Hostname() == "" || u.User != nil {
449			return fmt.Errorf("%s: %q must be http:// or https:// followed by a host, without credentials", envUpstreamURL, v)
450		}
451		// url.Parse accepts an empty port ("http://a:") and any digits ("a:99999").
452		if port := u.Port(); port != "" || strings.HasSuffix(u.Host, ":") {
453			if n, err := strconv.Atoi(port); err != nil || n < 1 || n > maxTCPPort {
454				return fmt.Errorf("%s: %q has a port outside 1-%d", envUpstreamURL, v, maxTCPPort)
455			}
456		}
457		return nil
458	}
459	
460	func validateHosts(hosts []string) error {
461		for _, h := range hosts {
462			if net.ParseIP(h) == nil && (len(h) > maxHostLen || !hostName.MatchString(h)) {
463				return fmt.Errorf("%s: %q is not an IP address or a host name", envHosts, h)
464			}
465		}
466		return nil
467	}
468	
469	func validateTimeout(name string, d time.Duration) error {
470		if d <= 0 {
471			return fmt.Errorf("%s: %s must be a positive duration", name, d)
472		}
473		return nil
474	}
475	
476	// validatePath refuses control characters; an empty path means "derived".
477	func validatePath(name, v string) error {
478		if len(v) > maxPathLen || strings.ContainsFunc(v, func(r rune) bool { return r < 0x20 || r == 0x7f }) {
479			return fmt.Errorf("%s: the path is too long or holds a control character", name)
480		}
481		return nil
482	}
