10	// render prints the manifests. It builds no dependency: it contacts nothing.
11	func (s *session) render() int {
12		out, err := nexusbench.Render(s.p)
13		if err != nil {
14			return s.fail(err)
15		}
16		if _, err := s.stdout.Write(out); err != nil {
17			return s.fail(err)
18		}
19		return exitOK
20	}
